-- Catmull-Rom sample of a key list at time t. n = number of values after the time.
function AnimClips.sample(keys, t: number, n: number)
	local first, last = keys[1], keys[#keys]
	local out = table.create(n, 0)
	if t <= first[1] then
		for c = 1, n do out[c] = first[c + 1] end
		return out
	end
	if t >= last[1] then
		for c = 1, n do out[c] = last[c + 1] end
		return out
	end
	local i = 1
	while keys[i + 1][1] < t do i += 1 end
	local k0, k1, k2, k3 = keys[math.max(1, i - 1)], keys[i], keys[i + 1], keys[math.min(#keys, i + 2)]
	local d1 = k2[1] - k1[1]
	local u = (t - k1[1]) / d1
	local u2, u3 = u * u, u * u * u
	for c = 2, n + 1 do
		local m1 = (k2[c] - k0[c]) / math.max(1e-3, k2[1] - k0[1]) * d1 * 0.9
		local m2 = (k3[c] - k1[c]) / math.max(1e-3, k3[1] - k1[1]) * d1 * 0.9
		out[c - 1] = (2 * u3 - 3 * u2 + 1) * k1[c] + (u3 - 2 * u2 + u) * m1 + (-2 * u3 + 3 * u2) * k2[c] + (u3 - u2) * m2
	end
	return out
end

-- Events between two clip times (from, to], in order.
function AnimClips.eventsBetween(clip, from: number, to: number)
	local out = {}
	for _, e in ipairs(clip.events or {}) do
		if e[1] > from and e[1] <= to then
			table.insert(out, e[2])
		end
	end
	return out
end

return AnimClips
